guidance.correct_example:
def fetch(a_url: str, a_timeout: float = 30.0) -> Result[str]:
    b_continue = True
    result: Result[str] = INVALID_RESULT
    try:
        response = requests.get(a_url, timeout=a_timeout)
    except requests.Timeout as e:
        result = Result.failure(f'Request timed out after {a_timeout}s: {e}')
        b_continue = False
    if b_continue:
        result = Result.success(response.text)
    return result

guidance.incorrect_example:
def fetch(a_url: str) -> Result[str]:
    response = requests.get(a_url)
    return Result.success(response.text)
